command:
// Opens the PF2e Automatic Resolution "Ongoing spells" window: active casts, Sustain, reviews and GM controls.
// Players see the casts they may view and the controls for their own spells.
const api = game.modules.get("pf2e-automatic-resolution")?.api;
if (!api) return ui.notifications.warn("PF2e Automatic Resolution isn't active in this world.");
api.ongoing.open();
